        if(!reader.ReadBytes(8).SequenceEqual(Magic))throw new InvalidDataException("Invalid incident package magic.");var version=reader.ReadUInt16();if(version is <1 or >IncidentPackage.SchemaVersion)throw new NotSupportedException($"Unsupported incident package schema {version}.");reader.ReadUInt16();var incidentId=new Guid(reader.ReadBytes(16).ToArray());var created=new DateTimeOffset(reader.ReadInt64(),TimeSpan.Zero);var sessionId=new Guid(reader.ReadBytes(16).ToArray());var reportType=(ErrorlyIncidentReportType)reader.ReadByte();reader.ReadByte();reader.ReadUInt16();var app=reader.ReadString();var environment=version>=2?reader.ReadString():null;var applicationVersion=version>=5?reader.ReadString():null;var message=reader.ReadString();var frequency=reader.ReadUInt64();var anchor=reader.ReadUInt64();var utc=reader.ReadInt64();var start=reader.ReadUInt64();var end=reader.ReadUInt64();var count=reader.ReadUInt32();if(count>IncidentPackageLimits.MaximumRecords)throw new InvalidDataException("Too many incident records.");
