    private static void Validate(IncidentPackage package){if(package.IncidentId==Guid.Empty||package.SessionId==Guid.Empty||package.CreatedUtc.Offset!=TimeSpan.Zero||package.ReportType!=ErrorlyIncidentReportType.Problem||package.QpcFrequency==0||package.EndTicks<package.StartTicks||package.Records.Count>IncidentPackageLimits.MaximumRecords||package.Exceptions.Count>8)throw new InvalidDataException("Incident metadata is invalid.");var frames=0;ulong prior=0;foreach(var record in package.Records){if(record.Payload.Length>IncidentPackageLimits.MaximumRecordPayloadBytes)throw new InvalidDataException("Record payload exceeds its size limit.");if(record.Sequence==0||record.Sequence<=prior)throw new InvalidDataException("Record ordering is invalid.");prior=record.Sequence;if(record.Type==1){frames++;if(record.Payload.Length>IncidentPackageLimits.MaximumJpegBytes)throw new InvalidDataException("JPEG exceeds its size limit.");}}if(frames>IncidentPackageLimits.MaximumFrames)throw new InvalidDataException("Too many frames.");ValidateString(package.ApplicationId);ValidateString(package.ApplicationVersion);ValidateString(package.SourceRevision);IncidentEnvironment.Normalize(package.Environment);ValidateString(package.ReportMessage);foreach(var exception in package.Exceptions){ValidateString(exception.Type);ValidateString(exception.RawStackTrace);if(exception.Frames.Count>IncidentPackageLimits.MaximumStackFrames)throw new InvalidDataException("Too many stack frames.");foreach(var frame in exception.Frames){ValidateString(frame.Method);ValidateString(frame.DeclaringType);ValidateString(frame.Assembly);ValidateString(frame.File);}}ValidateLogContext(package.ApplicationLogContext);ValidateRuntimeContext(package.RuntimeContext);
