    private static void ValidateLogContext(IncidentLogContext? context){if(context is null)return;if(context.Version!=IncidentLogContext.CurrentVersion||context.Entries.Count>IncidentPackageLimits.MaximumLogEntries||context.ProcessId<0)throw new InvalidDataException("Incident log context is invalid.");var bytes=0;ulong previous=0;foreach(var entry in context.Entries){if(entry.Timestamp.Offset!=TimeSpan.Zero||entry.Sequence==0||entry.Sequence<=previous||!Enum.IsDefined(typeof(IncidentLogLevel),entry.Level)||entry.Properties.Count>IncidentPackageLimits.MaximumLogProperties)throw new InvalidDataException("Incident log entry is invalid.");previous=entry.Sequence;var entryBytes=8+8+1;foreach(var value in new[]{entry.Category,entry.MessageTemplate,entry.RenderedMessage,entry.ExceptionType,entry.ExceptionMessage}){ValidateString(value);entryBytes+=StringBytes(value);}foreach(var property in entry.Properties){if(string.IsNullOrWhiteSpace(property.Name)||StringBytes(property.Name)>IncidentPackageLimits.MaximumLogPropertyBytes||StringBytes(property.Value)>IncidentPackageLimits.MaximumLogPropertyBytes)throw new InvalidDataException("Incident log property is invalid.");entryBytes+=StringBytes(property.Name)+StringBytes(property.Value);}if(entryBytes>IncidentPackageLimits.MaximumLogEntryBytes)throw new InvalidDataException("Incident log entry exceeds its size limit.");bytes+=entryBytes;if(bytes>IncidentPackageLimits.MaximumLogContextBytes)throw new InvalidDataException("Incident log context exceeds its size limit.");}}
    private static void ValidateRuntimeContext(IncidentRuntimeContext? context)
    {
        if(context is null)return;
        if(context.SchemaVersion!=1)throw new InvalidDataException("Unsupported runtime context version.");
        var bytes=0;foreach(var value in context.Values){var length=StringBytes(value);if(length>256)throw new InvalidDataException("Runtime context field exceeds its size limit.");bytes+=length;}
