    }
    private static void WriteRuntimeContext(BinaryWriter writer,IncidentRuntimeContext? context)
    {writer.Write(context is null?(byte)0:(byte)1);if(context is null)return;writer.Write(context.SchemaVersion);foreach(var value in context.Values)WriteString(writer,value);}
    private static IncidentRuntimeContext? ReadRuntimeContext(ref Reader reader)
