    private static int StringBytes(string? value)=>value is null?0:Encoding.UTF8.GetByteCount(value);
    private static void WriteLogContext(BinaryWriter writer,IncidentLogContext? context){writer.Write(context is null?(byte)0:(byte)1);if(context is null)return;writer.Write(context.Version);writer.Write((byte)((context.RateLimited?1:0)|(context.Truncated?2:0)));writer.Write(context.DroppedEntryCount);writer.Write(context.ProcessId);writer.Write((uint)context.Entries.Count);foreach(var entry in context.Entries){writer.Write(entry.Timestamp.UtcDateTime.Ticks);writer.Write(entry.Sequence);writer.Write((byte)entry.Level);WriteString(writer,entry.Category);WriteString(writer,entry.MessageTemplate);WriteString(writer,entry.RenderedMessage);WriteString(writer,entry.ExceptionType);WriteString(writer,entry.ExceptionMessage);writer.Write((uint)entry.Properties.Count);foreach(var property in entry.Properties){WriteString(writer,property.Name);WriteString(writer,property.Value);}}}
    private static IncidentLogContext? ReadLogContext(ref Reader reader){var present=reader.ReadByte();if(present==0)return null;if(present!=1)throw new InvalidDataException("Incident log context marker is invalid.");var version=reader.ReadByte();var flags=reader.ReadByte();if((flags&~3)!=0)throw new InvalidDataException("Incident log context flags are invalid.");var dropped=reader.ReadUInt32();var processId=reader.ReadInt32();var count=reader.ReadUInt32();if(count>IncidentPackageLimits.MaximumLogEntries)throw new InvalidDataException("Too many incident log entries.");var entries=new List<IncidentLogEntry>((int)count);for(var i=0u;i<count;i++){var timestamp=new DateTimeOffset(reader.ReadInt64(),TimeSpan.Zero);var sequence=reader.ReadUInt64();var level=(IncidentLogLevel)reader.ReadByte();var category=reader.ReadString();var template=reader.ReadString();var rendered=reader.ReadString();var exceptionType=reader.ReadString();var exceptionMessage=reader.ReadString();var propertyCount=reader.ReadUInt32();if(propertyCount>IncidentPackageLimits.MaximumLogProperties)throw new InvalidDataException("Too many incident log properties.");var properties=new List<IncidentLogProperty>((int)propertyCount);for(var j=0u;j<propertyCount;j++)properties.Add(new(reader.ReadString()??throw new InvalidDataException("Incident log property name is missing."),reader.ReadString()??throw new InvalidDataException("Incident log property value is missing.")));entries.Add(new(timestamp,sequence,level,category,template,rendered,exceptionType,exceptionMessage,properties));}return new(entries,dropped,(flags&1)!=0,(flags&2)!=0,processId,version);}
    private static void ValidateString(string? value){if(value is not null&&Encoding.UTF8.GetByteCount(value)>IncidentPackageLimits.MaximumStringBytes)throw new InvalidDataException("Incident string exceeds its size limit.");}
