    private ref struct Reader{private ReadOnlySpan<byte> source;private int offset;internal Reader(ReadOnlySpan<byte> source){this.source=source;offset=0;}internal bool AtEnd=>offset==source.Length;internal ReadOnlySpan<byte> ReadBytes(int length){if(length<0||length>source.Length-offset)throw new InvalidDataException("Incident package is truncated.");var value=source.Slice(offset,length);offset+=length;return value;}internal byte ReadByte()=>ReadBytes(1)[0];internal ushort ReadUInt16()=>BinaryPrimitives.ReadUInt16LittleEndian(ReadBytes(2));internal uint ReadUInt32()=>BinaryPrimitives.ReadUInt32LittleEndian(ReadBytes(4));internal int ReadInt32()=>BinaryPrimitives.ReadInt32LittleEndian(ReadBytes(4));internal ulong ReadUInt64()=>BinaryPrimitives.ReadUInt64LittleEndian(ReadBytes(8));internal long ReadInt64()=>BinaryPrimitives.ReadInt64LittleEndian(ReadBytes(8));internal string? ReadString(){var length=ReadUInt32();if(length==uint.MaxValue)return null;if(length>IncidentPackageLimits.MaximumStringBytes)throw new InvalidDataException("Incident string exceeds its size limit.");return Encoding.UTF8.GetString(ReadBytes((int)length).ToArray());}}
}


